def record(id, date, actors, actor_types, geo, arcs, topics, source_ids, titles, summaries, caveats,
           mechanisms, phase, relief, outcome, court, case_number='', artifact='court_filing', cyber=False):
    return dict(id=id, date=date, actors=actors, actor_types=actor_types, jurisdictions=geo,
        arcs=arcs, legal_topics=topics, source_ids=source_ids, artifact=artifact, cyber=cyber,
        title_ru=titles[0], title_en=titles[1], summary_ru=summaries[0], summary_en=summaries[1],
        caveat_ru=caveats[0], caveat_en=caveats[1], mechanism_ru=mechanisms[0], mechanism_en=mechanisms[1],
        legal_proceeding=dict(court=court, case_number=case_number, status_as_of=DATE,
            phase=phase, relief_requested_ru=relief[0], relief_requested_en=relief[1],
            outcome_ru=outcome[0], outcome_en=outcome[1],
            implementation_evidence='not_independently_established'))


